-- Esquema aislado de pruebas. No ejecutar sobre InsForge.
CREATE SCHEMA urh_votacion;
CREATE ROLE project_admin;
CREATE TABLE urh_votacion.usuario(id_usuario integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,id_persona integer,id_object varchar(100),id_tenant varchar(100),user_principal_name varchar(255),nombre varchar(255),activo boolean NOT NULL DEFAULT true);
CREATE TABLE urh_votacion.rol(id_rol integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,codigo varchar(30) NOT NULL UNIQUE,descripcion varchar(200));
CREATE TABLE urh_votacion.usuario_rol(id_usuario_rol integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,id_usuario integer,id_rol integer);
CREATE TABLE urh_votacion.evento(id_evento integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,dsc_evento varchar(255),dsc_sub_titulo varchar(255),dsc_mensaje varchar(255));
CREATE TABLE urh_votacion.segmento(id_segmento integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,dsc_segmento varchar(500),ord_segmento integer);
CREATE TABLE urh_votacion.personal(id_personal integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombres varchar(255),apellido_paterno varchar(255),apellido_materno varchar(255),activo boolean,id_segmento integer);
CREATE TABLE urh_votacion.padron(id_padron integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_evento integer,id_segmento integer,nom_padron varchar(255),dsc_padron varchar(255),fecha_creacion timestamptz NOT NULL DEFAULT now());
CREATE TABLE urh_votacion.padron_detalle(id_padron_detalle integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_padron integer,id_persona integer,habilitado boolean,fecha_registro timestamptz NOT NULL DEFAULT now());
CREATE TABLE urh_votacion.candidatura(id_candidatura integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_evento integer,id_persona integer,id_segmento integer,id_dependencia integer,dsc_nombre_completo varchar(255),dsc_cargo varchar(255),dsc_unidad varchar(255),dsc_segmento varchar(255),foto_url text,numero_lista integer,estado varchar(20),fecha_registro timestamptz);
CREATE TABLE urh_votacion.opcion_electoral(id_opcion_electoral bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,id_padron bigint NOT NULL,id_candidatura bigint,tipo_opcion varchar(20) NOT NULL,nombre varchar(200) NOT NULL,orden integer NOT NULL,activo boolean NOT NULL DEFAULT true);
CREATE TABLE urh_votacion.participacion_electoral(id_participacion bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,id_padron_detalle bigint NOT NULL,id_padron bigint NOT NULL,fecha_participacion timestamptz NOT NULL DEFAULT now(),estado varchar(20) NOT NULL DEFAULT 'CONFIRMADA',fecha_registro timestamptz NOT NULL DEFAULT now());
CREATE TABLE urh_votacion.voto(id_voto bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,id_participacion bigint NOT NULL,id_padron bigint NOT NULL,id_opcion_electoral bigint NOT NULL,fecha_emision timestamptz NOT NULL DEFAULT now());
